import base64
import io
output = {}
file = input.get('uploaded_file', {})
name = file.get('name','')
ext = name.lower().split('.')[-1] if '.' in name else ''
data_b64 = file.get('data','')
decoded = None
if data_b64:
 try:
 decoded = base64.b64decode(data_b64)
 except Exception:
 decoded = None
text_content = None
# Word to text
if ext in ('docx','doc') and decoded:
 try:
 from docx import Document
 doc = Document(io.BytesIO(decoded))
 paragraphs = [p.text for p in doc.paragraphs if p.text]
 text_content = '\n'.join(paragraphs)
 except Exception:
 text_content = None
# Excel to csv
elif ext in ('xls','xlsx') and decoded:
 try:
 import pandas as pd
 df = pd.read_excel(io.BytesIO(decoded))
 text_content = df.to_csv(index=False)
 except Exception:
 text_content = None
# plain text
elif ext in ('txt','csv') and decoded:
 try:
 text_content = decoded.decode('utf-8', errors='ignore')
 except Exception:
 text_content = None
# pdf or image: leave as fileUpload
else:
 if decoded and text_content is None:
 try:
 text_content = decoded.decode('utf-8', errors='ignore')
 except Exception:
 text_content = None
# Build prompt without double quotes to avoid JSON escaping issues
prompt_lines = []
prompt_lines.append('You are an assistant that extracts structured inventory data from a customer stock statement.')
prompt_lines.append('Extract the following:')
prompt_lines.append('- customer information: name, address, customer id if present and any identifying fields')
prompt_lines.append('- reporting period: start date, end date or period text')
prompt_lines.append('- For each line item extract product or sku or item, unit or packing, opening quantity, purchase or receipt quantity, sales or issue quantity, closing stock quantity. Return numeric quantities as numbers.')
prompt_lines.append('Return exactly one JSON object with keys: customer, period, items, notes. Do not include explanatory text.')
if ext in ('png','jpg','jpeg','tiff','bmp','gif') or ext == 'pdf':
 prompt_lines.append('The file is an image or scanned PDF. Perform OCR and extract tables and text as needed.')
else:
 prompt_lines.append('The file is text-based or was converted to text. Parse the text to extract header info and line items.')
prompt = '\n'.join(prompt_lines)
if text_content:
 output = { 'processingType': 'text', 'text_content': text_content, 'prompt': prompt, 'originalFileName': name }
else:
 output = { 'processingType': 'fileUpload', 'file_for_upload': file, 'prompt': prompt, 'originalFileName': name }

output = {}
prep = node_outputs.get('prepare_file', {})
prompt = prep.get('prompt', '')
upload = node_outputs.get('upload_to_gemini', {})
uploaded_file_info = upload.get('file', upload) or upload
file_uri = None
if isinstance(uploaded_file_info, dict):
 file_uri = uploaded_file_info.get('uri') or uploaded_file_info.get('name')
contents = []
if file_uri:
 contents = [ { 'parts': [ { 'fileData': { 'fileUri': file_uri } } ], 'role': 'user' } ]
else:
 contents = [ { 'parts': [ { 'text': prompt } ], 'role': 'user' } ]
systemInstruction = { 'parts': [ { 'text': prompt } ] }
output = { 'contents': contents, 'systemInstruction': systemInstruction }

output = {}
prep = node_outputs.get('prepare_file', {})
prompt = prep.get('prompt','')
text_content = prep.get('text_content','')
combined = prompt + '\n\n---BEGIN_EXTRACTED_TEXT---\n' + (text_content or '') + '\n---END_EXTRACTED_TEXT---'
contents = [ { 'parts': [ { 'text': combined } ], 'role': 'user' } ]
systemInstruction = { 'parts': [ { 'text': 'Extract the structured JSON as requested in the prompt. Return exactly one JSON object.' } ] }
output = { 'contents': contents, 'systemInstruction': systemInstruction }

output = {}
text_node = node_outputs.get('build_contents_text', {})
file_node = node_outputs.get('build_contents_after_upload', {})
contents = text_node.get('contents') if text_node and text_node.get('contents') else file_node.get('contents')
systemInstruction = text_node.get('systemInstruction') if text_node and text_node.get('systemInstruction') else file_node.get('systemInstruction')
output = { 'contents': contents, 'systemInstruction': systemInstruction }

import json
output = {}
resp = node_outputs.get('call_gemini', {})
candidates = resp.get('candidates') or []
text = None
if candidates and isinstance(candidates, list):
 first = candidates[0]
 content = first.get('content') or {}
 parts = content.get('parts') or []
 texts = []
 for p in parts:
 if isinstance(p, dict) and 'text' in p:
 texts.append(p.get('text'))
 if texts:
 text = '\n'.join(texts)
structured = None
if text:
 try:
 structured = json.loads(text)
 except Exception:
 structured = None
output = { 'structured': structured, 'raw_text': text, 'raw_response': resp }

output = {}
parsed = node_outputs.get('parse_gemini_output', {}).get('structured') or {}
rows = []
customer = parsed.get('customer') if isinstance(parsed, dict) else None
period = parsed.get('period') if isinstance(parsed, dict) else None
if customer and isinstance(customer, dict):
 for k, v in customer.items():
 rows.append([str(k), str(v)])
else:
 rows.append(['customer', ''])
if period and isinstance(period, dict):
 for k, v in period.items():
 rows.append([str(k), str(v)])
rows.append([])
rows.append(['Product/SKU/Item', 'Unit/Packing', 'Opening', 'Purchase/Receipt', 'Sales/Issue', 'Closing'])
items = parsed.get('items') if isinstance(parsed, dict) else None
if not items and isinstance(parsed, list):
 items = parsed
if items and isinstance(items, list):
 for it in items:
 product = it.get('product') if isinstance(it, dict) else ''
 unit = it.get('unit') if isinstance(it, dict) else (it.get('packing') if isinstance(it, dict) else '')
 opening = it.get('opening') if isinstance(it, dict) else None
 purchase = it.get('purchase') if isinstance(it, dict) else (it.get('receipt') if isinstance(it, dict) else None)
 sales = it.get('sales') if isinstance(it, dict) else (it.get('issue') if isinstance(it, dict) else None)
 closing = it.get('closing') if isinstance(it, dict) else None
 def norm(x):
 if x is None: return ''
 try:
 return float(str(x).replace(',', ''))
 except Exception:
 return str(x)
 rows.append([product or '', unit or '', norm(opening), norm(purchase), norm(sales), norm(closing)])
else:
 rows.append(['No line items found', '', '', '', '', ''])
output = { 'rows': rows }
